import * as T from './vendor/three.module.js';
export function rockGeometry(detail){
 const source=new T.IcosahedronGeometry(1,detail),input=source.attributes.position,vertices=[],indices=[],lookup=new Map();
 for(let i=0;i<input.count;i++){const x=input.getX(i),y=input.getY(i),z=input.getZ(i),key=[x,y,z].map(v=>v.toFixed(5)).join(',');let index=lookup.get(key);if(index===undefined){index=vertices.length/3;lookup.set(key,index);const k=1+.13*Math.sin(x*8+y*5)*Math.cos(z*7)+.05*Math.sin(y*19+z*11);vertices.push(x*k,y*k,z*k);}indices.push(index);}
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geometry.setIndex(indices);geometry.computeVertexNormals();source.dispose();return geometry;
}
export function rockMaterial(color=0x726b61){const material=new T.MeshStandardMaterial({color,roughness:1});material.onBeforeCompile=shader=>{shader.vertexShader='varying vec3 rockPoint;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nrockPoint=position;');shader.fragmentShader='varying vec3 rockPoint;\nfloat rockHash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}\nfloat rockNoise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(rockHash(i),rockHash(i+vec3(1,0,0)),f.x),mix(rockHash(i+vec3(0,1,0)),rockHash(i+vec3(1,1,0)),f.x),f.y),mix(mix(rockHash(i+vec3(0,0,1)),rockHash(i+vec3(1,0,1)),f.x),mix(rockHash(i+vec3(0,1,1)),rockHash(i+vec3(1,1,1)),f.x),f.y),f.z);}\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat rockGrain=rockNoise(rockPoint*22.)*.65+rockNoise(rockPoint*73.)*.35;diffuseColor.rgb*=.65+rockGrain*.65;');shader.fragmentShader=shader.fragmentShader.replace('#include <normal_fragment_maps>','#include <normal_fragment_maps>\nvec3 q0=dFdx(-vViewPosition),q1=dFdy(-vViewPosition),r0=cross(q1,normal),r1=cross(normal,q0);float determinant=dot(q0,r0);vec3 gradient=sign(determinant)*(dFdx(rockGrain)*r0+dFdy(rockGrain)*r1);normal=normalize(abs(determinant)*normal-gradient*.09);');};return material;}
